customizationCode.web:
/* Override escopado — as vars nascem no próprio .nds-badge. */
.meu-tema .nds-badge {
  --badge-bg: hsl(var(--muted));
  --badge-fg: hsl(var(--foreground));
  --badge-border: hsl(var(--border));
}

/* Cada variante re-aponta UMA coisa: a cor da borda, sempre a partir do
   token de mesmo nome. */
.meu-tema .nds-badge-warning {
  --badge-border: hsl(var(--warning));
}

